from rdkit import Chem
from rdkit.Chem import AllChem, rdMolDescriptors
from rdkit.Chem.EnumerateStereoisomers import EnumerateStereoisomers, StereoEnumerationOptions
import numpy as np
rw=Chem.RWMol()
labels={}
def atom(label,el='C'):
    idx=rw.AddAtom(Chem.Atom(el)); labels[label]=idx; return idx
def bond(l1,l2,b=1):
    rw.AddBond(labels[l1],labels[l2],{1:Chem.BondType.SINGLE,2:Chem.BondType.DOUBLE,3:Chem.BondType.AROMATIC}[b])
for n in 'ABCDEFGHIJKLM': atom(n)
# upper cyclopentenone A-B-C-D-E, fused to cyclopropane C-D-F
for a,b,t in [('A','B',2),('B','C',1),('C','D',1),('D','E',1),('E','A',1),('C','F',1),('D','F',1),('F','G',2)]:bond(a,b,t)
# norbornane H and I are bridgeheads; G is the one-carbon bridge
for a,b in [('G','H'),('G','I'),('H','J'),('J','K'),('K','I'),('H','L'),('L','M'),('M','I')]:bond(a,b)
atom('ketO','O'); bond('E','ketO',2)
for parent in ['A','D']:
    for lbl,el in [('acyl','C'),('oxo','O'),('alkoxy','O'),('methyl','C')]:atom(parent+lbl,el)
    bond(parent,parent+'acyl'); bond(parent+'acyl',parent+'oxo',2);bond(parent+'acyl',parent+'alkoxy');bond(parent+'alkoxy',parent+'methyl')
for parent in ['B','C']:
    for i in range(6):atom(parent+'Ph'+str(i))
    for i in range(6):bond(parent+'Ph'+str(i),parent+'Ph'+str((i+1)%6),3)
    bond(parent,parent+'Ph0')
m=rw.GetMol();Chem.SanitizeMol(m)
print('labels',labels)
print('formula',rdMolDescriptors.CalcMolFormula(m))
print('smiles',Chem.MolToSmiles(m))
print('centers',Chem.FindMolChiralCenters(m,includeUnassigned=True))
print('stereoinfo',[(x.type,x.centeredOn) for x in Chem.FindPotentialStereo(m)])
opts=StereoEnumerationOptions(onlyUnassigned=True,unique=True,tryEmbedding=False)
for i,iso in enumerate(EnumerateStereoisomers(m,options=opts)):
 print(i,Chem.MolToSmiles(iso))
 Chem.MolToMolFile(iso,f'isomer_{i}.mol')
Chem.MolToMolFile(m,'connectivity.mol')
import json
json.dump(labels,open('labels.json','w'))
PY
python build.py
